import type { HttpRequest } from "@iii-dev/helpers/http";
import type { IIIClient } from "iii-sdk";
import {
  buildEvidencePublicPayload,
  evidenceFunctionId,
  type EvidenceToolName,
} from "../mcp/evidence-tools.js";

type ApiResponse = { status_code: number; body: unknown };
type AuthCheck = (request: HttpRequest, secret: string | undefined) => ApiResponse | null;

export const EVIDENCE_API_ROUTES: ReadonlyArray<{ tool: EvidenceToolName; path: string }> = [
  { tool: "evidence_register_snapshot", path: "snapshot" },
  { tool: "evidence_record_source", path: "source" },
  { tool: "evidence_record_value", path: "value" },
  { tool: "evidence_record", path: "record" },
  { tool: "evidence_link_flow", path: "flow" },
  { tool: "evidence_record_hypothesis", path: "hypothesis" },
  { tool: "evidence_record_counter", path: "counter" },
  { tool: "evidence_record_validation", path: "validation" },
  { tool: "evidence_query", path: "query" },
  { tool: "evidence_review_chain", path: "review-chain" },
  { tool: "evidence_claim_coverage", path: "claim-coverage" },
  { tool: "evidence_reclassify_sink", path: "reclassify-sink" },
  { tool: "evidence_invalidate_paths", path: "invalidate-paths" },
  { tool: "evidence_invalidate_dependencies", path: "invalidate-dependencies" },
  { tool: "evidence_export_bundle", path: "export-bundle" },
];

export const EVIDENCE_API_ROUTE_COUNT = EVIDENCE_API_ROUTES.length;

export function registerEvidenceApi(
  sdk: IIIClient,
  secret: string | undefined,
  checkAuth: AuthCheck,
): void {
  for (const { tool, path } of EVIDENCE_API_ROUTES) {
    const functionId = `api::${tool.replaceAll("_", "-")}`;
    sdk.registerFunction(functionId, async (request: HttpRequest<Record<string, unknown>>): Promise<ApiResponse> => {
      const denied = checkAuth(request, secret);
      if (denied) return denied;
      const body = request.body;
      if (!body || typeof body !== "object" || Array.isArray(body)) {
        return { status_code: 400, body: { error: "JSON object body is required" } };
      }
      try {
        const payload = buildEvidencePublicPayload(tool, body);
        const result = await sdk.trigger({ function_id: evidenceFunctionId(tool), payload });
        return { status_code: 200, body: result };
      } catch (error) {
        return { status_code: 400, body: { error: (error as Error).message } };
      }
    });
    sdk.registerTrigger({
      type: "http",
      function_id: functionId,
      config: { api_path: `/agentmemory/evidence/${path}`, http_method: "POST" },
    });
  }
}
