import { createHash } from "node:crypto";
import type { IIIClient } from "iii-sdk";
import type { Origin } from "../types.js";
import type { StateKV } from "../state/kv.js";
import { KV, fingerprintId, generateId } from "../state/schema.js";
import { withKeyedLock } from "../state/keyed-mutex.js";
import { recordAudit } from "./audit.js";
import {
  STRONG_TRUST,
  type DependencyInputKind,
  type DependencyTargetKind,
  type EvidenceArtifact,
  type EvidenceDependency,
  type EvidenceIdempotencyRecord,
  type EvidenceLifecycleEvent,
  type EvidenceLink,
  type EvidenceRecord,
  type EvidenceSnapshot,
  type EvidenceStatus,
  type Finding,
  type FlowEdge,
  type FlowStatus,
  type Guard,
  type Hypothesis,
  type SourceReference,
  type ValidationRun,
  type ValueIdentity,
  type ValueRole,
} from "../evidence/types.js";

const HEX_REVISION = /^[0-9a-fA-F]{40,64}$/;
const SHA256 = /^[0-9a-fA-F]{64}$/;
const MAX_FIELD = 16_384;
const MAX_PATH = 4_096;
const MAX_RAW_BYTES = 8 * 1024 * 1024;
const MAX_PROJECTION = 16_384;
const MAX_QUERY = 4_096;
const MAX_LIMIT = 200;
const MAX_CHANGES = 10_000;
const MAX_CHAIN_DEPTH = 12;
const MAX_CHAINS = 200;

const ROLES: ReadonlySet<ValueRole> = new Set([
  "source", "sink", "transform", "param", "return", "field", "value",
]);
const FLOW_KINDS: ReadonlySet<FlowEdge["kind"]> = new Set([
  "intraprocedural", "interprocedural", "field", "return", "alias",
]);
const EVIDENCE_KINDS: ReadonlySet<EvidenceRecord["kind"]> = new Set([
  "static_analysis", "dataflow", "crash", "test", "source_excerpt", "build", "fuzz",
]);
const VALIDATION_KINDS: ReadonlySet<ValidationRun["kind"]> = new Set([
  "test", "build", "repro", "fuzz",
]);
const DEPENDENCY_KINDS: ReadonlySet<DependencyInputKind> = new Set([
  "path", "header", "generated_input", "build_flag", "analysis_model", "boundary_model", "config",
]);

type ErrorCode =
  | "INVALID_ARGUMENT"
  | "NOT_FOUND"
  | "REVISION_MISMATCH"
  | "CONFLICT"
  | "RESOURCE_LIMIT"
  | "BACKEND_UNAVAILABLE";

type EvidenceResult = Record<string, unknown> & {
  success: boolean;
  ok: boolean;
  error?: string;
  errorCode?: ErrorCode;
  data?: Record<string, unknown>;
};

type IdFactory = (prefix: string, suffix?: string) => string;

function ok(data: Record<string, unknown>): EvidenceResult {
  return { success: true, ok: true, data, ...data };
}

function fail(errorCode: ErrorCode, error: string): EvidenceResult {
  return { success: false, ok: false, errorCode, error };
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, item]) => item !== undefined)
      .sort(([a], [b]) => a.localeCompare(b));
    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${canonical(item)}`).join(",")}}`;
  }
  return JSON.stringify(value) ?? "null";
}

function agentOrigin(detail = "mcp-or-rest-caller"): Origin {
  return { channel: "agent", detail, capturedAt: new Date().toISOString() };
}

function validPath(path: unknown): path is string {
  if (typeof path !== "string" || !path || path.length > MAX_PATH || path.includes("\0")) return false;
  if (path.startsWith("/") || /^[A-Za-z]:[\\/]/.test(path)) return false;
  return !path.split(/[\\/]/).includes("..");
}

function validRange(startLine: unknown, endLine: unknown): boolean {
  return Number.isInteger(startLine) && Number.isInteger(endLine)
    && Number(startLine) >= 0 && Number(endLine) >= 0
    && (Number(endLine) === 0 || Number(endLine) >= Number(startLine));
}

function bounded(value: unknown, maximum = MAX_FIELD): value is string {
  return typeof value === "string" && value.length <= maximum;
}

function redactProjection(value: string): string {
  const withoutControls = value
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200D\u2060\uFEFF]/g, "")
    .replace(/-----BEGIN [^-]*PRIVATE KEY-----[\s\S]*?-----END [^-]*PRIVATE KEY-----/gi, "[REDACTED PRIVATE KEY]")
    .replace(/\b(api[_-]?key|token|secret|password)\s*[:=]\s*[^\s,;]+/gi, "$1=[REDACTED]")
    .split("\n")
    .map((line) => /(?:ignore (?:all |any )?(?:previous|prior) instructions|system prompt|developer message)/i.test(line)
      ? "[instruction-like content removed]"
      : line)
    .join("\n");
  return withoutControls.slice(0, MAX_PROJECTION);
}

async function snapshotOrError(kv: StateKV, snapshotId: unknown): Promise<EvidenceSnapshot | EvidenceResult> {
  if (typeof snapshotId !== "string" || !snapshotId) return fail("INVALID_ARGUMENT", "snapshotId is required");
  const snapshot = await kv.get<EvidenceSnapshot>(KV.evidenceSnapshots, snapshotId);
  return snapshot ?? fail("NOT_FOUND", `unknown snapshot ${snapshotId}`);
}

function isFailure(value: EvidenceSnapshot | EvidenceResult): value is EvidenceResult {
  return "success" in value && value.success === false;
}

async function lifecycle(
  kv: StateKV,
  recordKind: EvidenceLifecycleEvent["recordKind"],
  recordId: string,
  event: EvidenceLifecycleEvent["event"],
  snapshotId?: string,
  reason?: string,
  replacementId?: string,
): Promise<void> {
  const item: EvidenceLifecycleEvent = {
    id: generateId("evlife"), recordKind, recordId, event,
    createdTs: new Date().toISOString(),
    ...(snapshotId ? { snapshotId } : {}),
    ...(reason ? { reason } : {}),
    ...(replacementId ? { replacementId } : {}),
  };
  await kv.set(KV.evidenceLifecycle, item.id, item);
}

async function addDependency(
  kv: StateKV,
  snapshotId: string,
  inputKind: DependencyInputKind,
  inputKey: string,
  targetKind: DependencyTargetKind,
  targetId: string,
): Promise<void> {
  const id = fingerprintId("evdep", `${snapshotId}\0${inputKind}\0${inputKey}\0${targetKind}\0${targetId}`);
  const dependency: EvidenceDependency = {
    id, snapshotId, inputKind, inputKey, targetKind, targetId,
    createdTs: new Date().toISOString(),
  };
  await kv.set(KV.evidenceDependencies, id, dependency);
}

async function mutation(
  kv: StateKV,
  operation: string,
  payload: Record<string, unknown>,
  idempotencyKey: unknown,
  execute: (id: IdFactory) => Promise<EvidenceResult>,
): Promise<EvidenceResult> {
  if (idempotencyKey !== undefined && typeof idempotencyKey !== "string") {
    return fail("INVALID_ARGUMENT", "idempotencyKey must be a string");
  }
  const key = String(idempotencyKey ?? "");
  if (key.length > 256) return fail("RESOURCE_LIMIT", "idempotencyKey exceeds 256 characters");
  const payloadHash = sha256(canonical(payload));
  const id: IdFactory = (prefix, suffix = "") => key
    ? fingerprintId(prefix, `${operation}\0${key}\0${payloadHash}\0${suffix}`)
    : generateId(prefix);
  if (!key) {
    try { return await execute(id); }
    catch (error) { return fail("BACKEND_UNAVAILABLE", `evidence backend error: ${(error as Error).message}`); }
  }
  return withKeyedLock(`evidence-idempotency:${key}`, async () => {
    const prior = await kv.get<EvidenceIdempotencyRecord>(KV.evidenceIdempotency, key);
    if (prior) {
      if (prior.operation !== operation || prior.payloadHash !== payloadHash) {
        return fail("CONFLICT", "idempotency key was already used with different arguments");
      }
      const replay = structuredClone(prior.result) as EvidenceResult;
      return { ...replay, idempotentReplay: true };
    }
    try {
      const result = await execute(id);
      if (result.success) {
        const record: EvidenceIdempotencyRecord = {
          key, operation, payloadHash, result, createdTs: new Date().toISOString(),
        };
        await kv.set(KV.evidenceIdempotency, key, record);
      }
      return result;
    } catch (error) {
      return fail("BACKEND_UNAVAILABLE", `evidence backend error: ${(error as Error).message}`);
    }
  });
}

async function storeArtifact(kv: StateKV, content: string): Promise<EvidenceArtifact> {
  const sizeBytes = Buffer.byteLength(content, "utf8");
  if (sizeBytes > MAX_RAW_BYTES) throw new Error(`artifact exceeds ${MAX_RAW_BYTES} bytes`);
  const digest = sha256(content);
  const existing = await kv.get<EvidenceArtifact>(KV.evidenceArtifacts, digest);
  if (existing) {
    if (sha256(existing.content) !== digest || existing.sizeBytes !== Buffer.byteLength(existing.content, "utf8")) {
      throw new Error(`stored artifact ${digest} failed integrity validation`);
    }
    return existing;
  }
  const artifact: EvidenceArtifact = {
    sha256: digest, sizeBytes, content, encoding: "utf8", createdTs: new Date().toISOString(),
  };
  await kv.set(KV.evidenceArtifacts, digest, artifact);
  return artifact;
}

async function registerSnapshot(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const repoId = data.repoId;
  const commitId = data.commitId;
  const dirty = data.dirty === true;
  const patchDigest = data.patchDigest;
  const treeDigest = data.treeDigest;
  if (!bounded(repoId) || !repoId.trim() || typeof commitId !== "string" || !HEX_REVISION.test(commitId)) {
    return fail("INVALID_ARGUMENT", "repoId and a full 40-64 character hexadecimal commitId are required");
  }
  if (dirty && (typeof patchDigest !== "string" || !SHA256.test(patchDigest))) {
    return fail("INVALID_ARGUMENT", "dirty snapshots require a SHA-256 patchDigest");
  }
  if (!dirty && patchDigest) return fail("INVALID_ARGUMENT", "clean snapshots cannot include patchDigest");
  if (treeDigest && (typeof treeDigest !== "string" || !SHA256.test(treeDigest))) {
    return fail("INVALID_ARGUMENT", "treeDigest must be a SHA-256 digest");
  }
  for (const field of [data.scope, data.platform, data.indexId]) {
    if (field !== undefined && !bounded(field)) return fail("RESOURCE_LIMIT", "snapshot metadata exceeds its size limit");
  }
  const payload = { repoId, commitId, dirty, patchDigest, treeDigest, scope: data.scope, platform: data.platform, indexId: data.indexId };
  return mutation(kv, "register_snapshot", payload, data.idempotencyKey, async () => {
    const id = fingerprintId("evsnap", canonical(payload));
    const existing = await kv.get<EvidenceSnapshot>(KV.evidenceSnapshots, id);
    if (existing) return ok({ snapshot: existing, snapshotId: id, deduped: true });
    const snapshot: EvidenceSnapshot = {
      id, repoId: repoId.trim(), commitId: commitId.toLowerCase(), dirty,
      createdTs: new Date().toISOString(),
      ...(typeof patchDigest === "string" ? { patchDigest: patchDigest.toLowerCase() } : {}),
      ...(typeof treeDigest === "string" ? { treeDigest: treeDigest.toLowerCase() } : {}),
      ...(typeof data.scope === "string" && data.scope ? { scope: data.scope } : {}),
      ...(typeof data.platform === "string" && data.platform ? { platform: data.platform } : {}),
      ...(typeof data.indexId === "string" && data.indexId ? { indexId: data.indexId } : {}),
    };
    await kv.set(KV.evidenceSnapshots, id, snapshot);
    await lifecycle(kv, "snapshot", id, "created", id);
    await recordAudit(kv, "evidence_snapshot", "ev::register-snapshot", [id], { repoId, commitId, dirty });
    return ok({ snapshot, snapshotId: id });
  });
}

async function recordSourceReference(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  if (!validPath(data.path)) return fail("INVALID_ARGUMENT", "path must be a bounded repository-relative path without '..'");
  const startLine = data.startLine ?? 0;
  const endLine = data.endLine ?? 0;
  if (!validRange(startLine, endLine)) return fail("INVALID_ARGUMENT", "source line range is invalid");
  if (data.excerpt !== undefined && !bounded(data.excerpt, MAX_RAW_BYTES)) return fail("RESOURCE_LIMIT", "excerpt is too large");
  for (const field of [data.symbolId, data.language]) {
    if (field !== undefined && !bounded(field)) return fail("RESOURCE_LIMIT", "source-reference metadata is too large");
  }
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_source_reference", payload, data.idempotencyKey, async (idFor) => {
    const excerpt = typeof data.excerpt === "string" ? redactProjection(data.excerpt) : undefined;
    const reference: SourceReference = {
      id: idFor("evsrc"), snapshotId: snapshot.id, path: data.path as string,
      startLine: Number(startLine), endLine: Number(endLine), state: "current",
      createdTs: new Date().toISOString(),
      ...(typeof data.symbolId === "string" && data.symbolId ? { symbolId: data.symbolId } : {}),
      ...(typeof data.language === "string" && data.language ? { language: data.language } : {}),
      ...(excerpt ? { excerpt, fileDigest: sha256(data.excerpt as string) } : {}),
    };
    await kv.set(KV.evidenceSourceRefs, reference.id, reference);
    await addDependency(kv, snapshot.id, "path", reference.path, "source_ref", reference.id);
    await lifecycle(kv, "source_ref", reference.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_source_ref", "ev::record-source", [reference.id], { snapshotId: snapshot.id, path: reference.path });
    return ok({ sourceReference: reference, sourceReferenceId: reference.id });
  });
}

async function recordValueIdentity(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  if (!validPath(data.path) || !bounded(data.valueName) || !data.valueName) {
    return fail("INVALID_ARGUMENT", "path and valueName are required and must be bounded");
  }
  const role = (data.role ?? "value") as ValueRole;
  if (!ROLES.has(role)) return fail("INVALID_ARGUMENT", `invalid value role: ${String(role)}`);
  if (role !== "sink" && data.sinkType) return fail("INVALID_ARGUMENT", "sinkType is valid only for sink identities");
  const startLine = data.startLine ?? 0;
  const endLine = data.endLine ?? 0;
  if (!validRange(startLine, endLine)) return fail("INVALID_ARGUMENT", "value line range is invalid");
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_value_identity", payload, data.idempotencyKey, async (idFor) => {
    const value: ValueIdentity = {
      id: idFor("evval"), snapshotId: snapshot.id, path: data.path as string,
      valueName: data.valueName as string, startLine: Number(startLine), endLine: Number(endLine),
      role, origin: agentOrigin(), state: "current", version: 1, createdTs: new Date().toISOString(),
      ...(typeof data.symbolId === "string" && data.symbolId ? { symbolId: data.symbolId } : {}),
      ...(role === "sink" && typeof data.sinkType === "string" && data.sinkType ? { sinkType: data.sinkType } : {}),
      ...(typeof data.language === "string" && data.language ? { language: data.language } : {}),
    };
    await kv.set(KV.evidenceValues, value.id, value);
    await addDependency(kv, snapshot.id, "path", value.path, "value", value.id);
    await lifecycle(kv, "value", value.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_value", "ev::record-value", [value.id], { snapshotId: snapshot.id, role, path: value.path });
    return ok({ valueIdentity: value, valueIdentityId: value.id });
  });
}

function parseDependencies(value: unknown): Array<{ kind: DependencyInputKind; key: string }> | EvidenceResult {
  if (value === undefined) return [];
  if (!Array.isArray(value) || value.length > MAX_CHANGES) return fail("RESOURCE_LIMIT", `dependencies must be an array of at most ${MAX_CHANGES} items`);
  const result: Array<{ kind: DependencyInputKind; key: string }> = [];
  for (const item of value) {
    if (!item || typeof item !== "object") return fail("INVALID_ARGUMENT", "each dependency must contain kind and key");
    const { kind, key } = item as { kind?: unknown; key?: unknown };
    if (typeof kind !== "string" || !DEPENDENCY_KINDS.has(kind as DependencyInputKind) || !bounded(key) || !key) {
      return fail("INVALID_ARGUMENT", "dependency kind or key is invalid");
    }
    result.push({ kind: kind as DependencyInputKind, key });
  }
  return result;
}

async function recordEvidence(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  const kind = (data.kind ?? "static_analysis") as EvidenceRecord["kind"];
  if (!EVIDENCE_KINDS.has(kind)) return fail("INVALID_ARGUMENT", `invalid evidence kind: ${String(kind)}`);
  if (typeof data.raw !== "string" && typeof data.projection !== "string") {
    return fail("INVALID_ARGUMENT", "raw or projection evidence is required");
  }
  if (typeof data.raw === "string" && Buffer.byteLength(data.raw, "utf8") > MAX_RAW_BYTES) {
    return fail("RESOURCE_LIMIT", `raw evidence exceeds ${MAX_RAW_BYTES} bytes`);
  }
  if (typeof data.projection === "string" && data.projection.length > MAX_RAW_BYTES) {
    return fail("RESOURCE_LIMIT", "evidence projection exceeds the input limit");
  }
  if (data.valueIdentityId) {
    const value = await kv.get<ValueIdentity>(KV.evidenceValues, String(data.valueIdentityId));
    if (!value) return fail("NOT_FOUND", `unknown value identity ${String(data.valueIdentityId)}`);
    if (value.snapshotId !== snapshot.id) return fail("REVISION_MISMATCH", "evidence and value identity belong to different snapshots");
  }
  const dependencies = parseDependencies(data.dependencies);
  if (!Array.isArray(dependencies)) return dependencies;
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_analysis_evidence", payload, data.idempotencyKey, async (idFor) => {
    const requested = String(data.status ?? "observed") as EvidenceStatus;
    const allowed = new Set<EvidenceStatus>(["observed", "supported", "reproduced", "rejected", "stale"]);
    if (!allowed.has(requested)) return fail("INVALID_ARGUMENT", `invalid evidence status: ${requested}`);
    const status: EvidenceStatus = requested === "reproduced" ? "observed" : requested;
    const artifact = typeof data.raw === "string" ? await storeArtifact(kv, data.raw) : undefined;
    const projectionInput = typeof data.projection === "string" ? data.projection : (data.raw as string | undefined);
    const record: EvidenceRecord = {
      id: idFor("evrec"), snapshotId: snapshot.id, kind, status, trust: "agent_asserted",
      origin: agentOrigin(typeof data.tool === "string" && data.tool ? data.tool : undefined),
      state: status === "stale" ? "stale" : "current", version: 1, createdTs: new Date().toISOString(),
      ...(artifact ? { rawArtifactSha256: artifact.sha256 } : {}),
      ...(projectionInput ? { projection: redactProjection(projectionInput) } : {}),
      ...(typeof data.valueIdentityId === "string" && data.valueIdentityId ? { valueIdentityId: data.valueIdentityId } : {}),
      ...(typeof data.tool === "string" && data.tool ? { tool: data.tool.slice(0, MAX_FIELD) } : {}),
      ...(typeof data.toolVersion === "string" && data.toolVersion ? { toolVersion: data.toolVersion.slice(0, MAX_FIELD) } : {}),
      ...(typeof data.queryId === "string" && data.queryId ? { queryId: data.queryId.slice(0, MAX_FIELD) } : {}),
    };
    await kv.set(KV.evidenceRecords, record.id, record);
    if (record.valueIdentityId) await addDependency(kv, snapshot.id, "path", (await kv.get<ValueIdentity>(KV.evidenceValues, record.valueIdentityId))!.path, "evidence", record.id);
    for (const dependency of dependencies) await addDependency(kv, snapshot.id, dependency.kind, dependency.key, "evidence", record.id);
    await lifecycle(kv, "evidence", record.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_record", "ev::record-evidence", [record.id], { snapshotId: snapshot.id, kind, storedStatus: status, trust: record.trust });
    return ok({ evidence: record, evidenceId: record.id, storedStatus: status, storedTrust: record.trust });
  });
}

async function linkFlow(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  const src = await kv.get<ValueIdentity>(KV.evidenceValues, String(data.srcVid ?? ""));
  const dst = await kv.get<ValueIdentity>(KV.evidenceValues, String(data.dstVid ?? ""));
  if (!src || !dst) return fail("NOT_FOUND", "flow edge references an unknown value identity");
  if (src.snapshotId !== snapshot.id || dst.snapshotId !== snapshot.id) {
    return fail("REVISION_MISMATCH", "flow edge value identities must belong to the same snapshot");
  }
  const kind = (data.kind ?? "interprocedural") as FlowEdge["kind"];
  if (!FLOW_KINDS.has(kind)) return fail("INVALID_ARGUMENT", `invalid flow kind: ${String(kind)}`);
  let evidence: EvidenceRecord | null = null;
  if (data.evidenceId) {
    evidence = await kv.get<EvidenceRecord>(KV.evidenceRecords, String(data.evidenceId));
    if (!evidence) return fail("NOT_FOUND", `unknown evidence ${String(data.evidenceId)}`);
    if (evidence.snapshotId !== snapshot.id) return fail("REVISION_MISMATCH", "flow and evidence belong to different snapshots");
  }
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "link_flow_transition", payload, data.idempotencyKey, async (idFor) => {
    const requested = String(data.status ?? "hypothesis") as FlowStatus;
    const allowed = new Set<FlowStatus>(["hypothesis", "supported", "demonstrated", "rejected", "blocked", "stale"]);
    if (!allowed.has(requested)) return fail("INVALID_ARGUMENT", `invalid flow status: ${requested}`);
    let status: FlowStatus = requested;
    if (requested === "demonstrated") status = evidence?.status === "reproduced" && STRONG_TRUST.has(evidence.trust) ? "supported" : "hypothesis";
    if (requested === "supported" && (!evidence || evidence.state !== "current" || evidence.status === "rejected")) status = "hypothesis";
    const edge: FlowEdge = {
      id: idFor("evflow"), snapshotId: snapshot.id, srcVid: src.id, dstVid: dst.id, kind, status,
      trust: "agent_asserted", provenance: agentOrigin(), validFromCommit: snapshot.commitId,
      state: status === "stale" ? "stale" : "current", version: 1, isLatest: true,
      createdTs: new Date().toISOString(),
      ...(evidence ? { evidenceId: evidence.id } : {}),
      ...(typeof data.callerSymbol === "string" && data.callerSymbol ? { callerSymbol: data.callerSymbol } : {}),
      ...(typeof data.calleeSymbol === "string" && data.calleeSymbol ? { calleeSymbol: data.calleeSymbol } : {}),
      ...(Number.isInteger(data.argIndex) && Number(data.argIndex) >= 0 ? { argIndex: Number(data.argIndex) } : {}),
      ...(typeof data.paramName === "string" && data.paramName ? { paramName: data.paramName } : {}),
    };
    await kv.set(KV.evidenceFlows, edge.id, edge);
    await addDependency(kv, snapshot.id, "path", src.path, "flow", edge.id);
    await addDependency(kv, snapshot.id, "path", dst.path, "flow", edge.id);
    await lifecycle(kv, "flow", edge.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_flow", "ev::link-flow", [edge.id], { snapshotId: snapshot.id, requestedStatus: requested, storedStatus: status, trust: edge.trust });
    return ok({ flowEdge: edge, flowEdgeId: edge.id, storedStatus: status, storedTrust: edge.trust });
  });
}

async function recordHypothesis(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  if (!bounded(data.statement) || !data.statement.trim()) return fail("INVALID_ARGUMENT", "statement is required");
  let snapshot: EvidenceSnapshot | undefined;
  if (data.snapshotId) {
    const found = await snapshotOrError(kv, data.snapshotId);
    if (isFailure(found)) return found;
    snapshot = found;
  }
  const evidenceIds = Array.isArray(data.supportingEvidenceIds) ? data.supportingEvidenceIds.map(String) : [];
  const flowIds = Array.isArray(data.supportingFlowEdgeIds) ? data.supportingFlowEdgeIds.map(String) : [];
  if (evidenceIds.length + flowIds.length > MAX_CHANGES) return fail("RESOURCE_LIMIT", "too many supporting records");
  const supportSnapshotIds = new Set<string>();
  for (const evidenceId of evidenceIds) {
    const evidence = await kv.get<EvidenceRecord>(KV.evidenceRecords, evidenceId);
    if (!evidence) return fail("NOT_FOUND", `unknown evidence ${evidenceId}`);
    supportSnapshotIds.add(evidence.snapshotId);
    if (snapshot && evidence.snapshotId !== snapshot.id) return fail("REVISION_MISMATCH", "hypothesis support crosses snapshots");
  }
  for (const flowId of flowIds) {
    const edge = await kv.get<FlowEdge>(KV.evidenceFlows, flowId);
    if (!edge) return fail("NOT_FOUND", `unknown flow edge ${flowId}`);
    supportSnapshotIds.add(edge.snapshotId);
    if (snapshot && edge.snapshotId !== snapshot.id) return fail("REVISION_MISMATCH", "hypothesis support crosses snapshots");
  }
  if (supportSnapshotIds.size > 1) return fail("REVISION_MISMATCH", "hypothesis support crosses snapshots");
  if (!snapshot && supportSnapshotIds.size === 1) {
    const inferred = await snapshotOrError(kv, [...supportSnapshotIds][0]);
    if (isFailure(inferred)) return inferred;
    snapshot = inferred;
  }
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_hypothesis", payload, data.idempotencyKey, async (idFor) => {
    const now = new Date().toISOString();
    const hypothesis: Hypothesis = {
      id: idFor("evhyp"), statement: data.statement as string, status: "open",
      supportingEvidenceIds: evidenceIds, supportingFlowEdgeIds: flowIds,
      state: "current", createdTs: now, updatedTs: now,
      ...(snapshot ? { snapshotId: snapshot.id } : {}),
      ...(typeof data.invariant === "string" && data.invariant ? { invariant: data.invariant.slice(0, MAX_FIELD) } : {}),
      ...(typeof data.scope === "string" && data.scope ? { scope: data.scope.slice(0, MAX_FIELD) } : {}),
      ...(typeof data.nextAction === "string" && data.nextAction ? { nextAction: data.nextAction.slice(0, MAX_FIELD) } : {}),
    };
    await kv.set(KV.evidenceHypotheses, hypothesis.id, hypothesis);
    for (const evidenceId of evidenceIds) {
      const link: EvidenceLink = { id: idFor("evlink", `support-e-${evidenceId}`), hypothesisId: hypothesis.id, relation: "supports", evidenceId, createdTs: now };
      await kv.set(KV.evidenceLinks, link.id, link);
    }
    for (const flowEdgeId of flowIds) {
      const link: EvidenceLink = { id: idFor("evlink", `support-f-${flowEdgeId}`), hypothesisId: hypothesis.id, relation: "supports", flowEdgeId, createdTs: now };
      await kv.set(KV.evidenceLinks, link.id, link);
    }
    if (snapshot) await lifecycle(kv, "hypothesis", hypothesis.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_hypothesis", "ev::record-hypothesis", [hypothesis.id], { snapshotId: snapshot?.id ?? null });
    return ok({ hypothesis, hypothesisId: hypothesis.id });
  });
}

async function recordCounterEvidence(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const hypothesis = await kv.get<Hypothesis>(KV.evidenceHypotheses, String(data.hypothesisId ?? ""));
  if (!hypothesis) return fail("NOT_FOUND", `unknown hypothesis ${String(data.hypothesisId ?? "")}`);
  if (!data.evidenceId && !data.flowEdgeId) return fail("INVALID_ARGUMENT", "evidenceId or flowEdgeId is required");
  let strong = false;
  let linkedSnapshotId: string | undefined;
  if (data.evidenceId) {
    const evidence = await kv.get<EvidenceRecord>(KV.evidenceRecords, String(data.evidenceId));
    if (!evidence) return fail("NOT_FOUND", `unknown evidence ${String(data.evidenceId)}`);
    if (hypothesis.snapshotId && evidence.snapshotId !== hypothesis.snapshotId) return fail("REVISION_MISMATCH", "counter-evidence crosses snapshots");
    linkedSnapshotId = evidence.snapshotId;
    strong = evidence.status === "reproduced" && STRONG_TRUST.has(evidence.trust);
  }
  if (data.flowEdgeId) {
    const edge = await kv.get<FlowEdge>(KV.evidenceFlows, String(data.flowEdgeId));
    if (!edge) return fail("NOT_FOUND", `unknown flow edge ${String(data.flowEdgeId)}`);
    if (hypothesis.snapshotId && edge.snapshotId !== hypothesis.snapshotId) return fail("REVISION_MISMATCH", "counter-evidence crosses snapshots");
    if (linkedSnapshotId && linkedSnapshotId !== edge.snapshotId) return fail("REVISION_MISMATCH", "counter-evidence crosses snapshots");
    linkedSnapshotId = edge.snapshotId;
    strong ||= edge.status === "rejected" && STRONG_TRUST.has(edge.trust);
  }
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_counter_evidence", payload, data.idempotencyKey, async (idFor) => {
    const link: EvidenceLink = {
      id: idFor("evlink"), hypothesisId: hypothesis.id, relation: "contradicts",
      createdTs: new Date().toISOString(),
      ...(data.evidenceId ? { evidenceId: String(data.evidenceId) } : {}),
      ...(data.flowEdgeId ? { flowEdgeId: String(data.flowEdgeId) } : {}),
      ...(typeof data.rationale === "string" && data.rationale ? { rationale: data.rationale.slice(0, MAX_FIELD) } : {}),
    };
    await kv.set(KV.evidenceLinks, link.id, link);
    const updated: Hypothesis = {
      ...hypothesis,
      status: strong ? "refuted" : "challenged",
      updatedTs: new Date().toISOString(),
      ...(!hypothesis.snapshotId && linkedSnapshotId ? { snapshotId: linkedSnapshotId } : {}),
    };
    await kv.set(KV.evidenceHypotheses, updated.id, updated);
    await recordAudit(kv, "evidence_counter", "ev::record-counter", [link.id, hypothesis.id], { strong });
    return ok({ link, linkId: link.id, hypothesisStatus: updated.status });
  });
}

async function recordValidation(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  let snapshot: EvidenceSnapshot | undefined;
  if (data.snapshotId) {
    const found = await snapshotOrError(kv, data.snapshotId);
    if (isFailure(found)) return found;
    snapshot = found;
  }
  let hypothesis: Hypothesis | null = null;
  if (data.hypothesisId) {
    hypothesis = await kv.get<Hypothesis>(KV.evidenceHypotheses, String(data.hypothesisId));
    if (!hypothesis) return fail("NOT_FOUND", `unknown hypothesis ${String(data.hypothesisId)}`);
    if (snapshot && hypothesis.snapshotId && hypothesis.snapshotId !== snapshot.id) return fail("REVISION_MISMATCH", "validation and hypothesis belong to different snapshots");
    if (!snapshot && hypothesis.snapshotId) {
      const inferred = await snapshotOrError(kv, hypothesis.snapshotId);
      if (isFailure(inferred)) return inferred;
      snapshot = inferred;
    }
  }
  const kind = (data.kind ?? "test") as ValidationRun["kind"];
  if (!VALIDATION_KINDS.has(kind)) return fail("INVALID_ARGUMENT", `invalid validation kind: ${String(kind)}`);
  for (const digest of [data.buildDigest, data.configDigest]) {
    if (digest && (typeof digest !== "string" || !SHA256.test(digest))) return fail("INVALID_ARGUMENT", "build/config digests must be SHA-256 values");
  }
  if (typeof data.logs === "string" && Buffer.byteLength(data.logs, "utf8") > MAX_RAW_BYTES) return fail("RESOURCE_LIMIT", "validation logs are too large");
  const dependencies = parseDependencies(data.dependencies);
  if (!Array.isArray(dependencies)) return dependencies;
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "record_validation_run", payload, data.idempotencyKey, async (idFor) => {
    const requested = String(data.status ?? "not_run");
    const allowed = new Set(["not_run", "running", "passed", "failed", "inconclusive"]);
    if (!allowed.has(requested)) return fail("INVALID_ARGUMENT", `invalid validation status: ${requested}`);
    const status = (requested === "passed" ? "inconclusive" : requested) as ValidationRun["status"];
    const artifact = typeof data.logs === "string" ? await storeArtifact(kv, data.logs) : undefined;
    const run: ValidationRun = {
      id: idFor("evrun"), kind, status, trust: "agent_asserted", origin: agentOrigin(),
      state: "current", createdTs: new Date().toISOString(),
      ...(snapshot ? { snapshotId: snapshot.id } : {}),
      ...(hypothesis ? { hypothesisId: hypothesis.id } : {}),
      ...(artifact ? { logArtifactSha256: artifact.sha256 } : {}),
      ...(typeof data.repeatSummary === "string" && data.repeatSummary ? { repeatSummary: redactProjection(data.repeatSummary) } : {}),
      ...(typeof data.buildDigest === "string" ? { buildDigest: data.buildDigest.toLowerCase() } : {}),
      ...(typeof data.configDigest === "string" ? { configDigest: data.configDigest.toLowerCase() } : {}),
    };
    await kv.set(KV.evidenceValidationRuns, run.id, run);
    if (snapshot) for (const dependency of dependencies) await addDependency(kv, snapshot.id, dependency.kind, dependency.key, "validation", run.id);
    if (snapshot) await lifecycle(kv, "validation", run.id, "created", snapshot.id);
    await recordAudit(kv, "evidence_validation", "ev::record-validation", [run.id], { requestedStatus: requested, storedStatus: status });
    return ok({ validationRun: run, validationRunId: run.id, storedStatus: status });
  });
}

async function queryEvidence(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const limit = Number(data.limit ?? 20);
  const offset = Number(data.offset ?? 0);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) return fail("RESOURCE_LIMIT", `limit must be 1-${MAX_LIMIT}`);
  if (!Number.isInteger(offset) || offset < 0 || offset > 1_000_000) return fail("RESOURCE_LIMIT", "offset is outside the allowed range");
  const text = typeof data.text === "string" ? data.text : "";
  if (text.length > MAX_QUERY) return fail("RESOURCE_LIMIT", `query exceeds ${MAX_QUERY} characters`);
  const snapshotId = typeof data.snapshotId === "string" && data.snapshotId ? data.snapshotId : undefined;
  if (snapshotId) {
    const snapshot = await snapshotOrError(kv, snapshotId);
    if (isFailure(snapshot)) return snapshot;
  }
  const values = await kv.list<ValueIdentity>(KV.evidenceValues);
  const valueMap = new Map(values.map((value) => [value.id, value]));
  const needle = text.toLocaleLowerCase();
  const filtered = (await kv.list<EvidenceRecord>(KV.evidenceRecords)).filter((record) => {
    if (data.kind && record.kind !== data.kind) return false;
    if (data.status && record.status !== data.status) return false;
    const value = record.valueIdentityId ? valueMap.get(record.valueIdentityId) : undefined;
    if (data.path && value?.path !== data.path) return false;
    if (data.symbolId && value?.symbolId !== data.symbolId) return false;
    if (needle && ![record.projection, record.tool, record.queryId, value?.path, value?.symbolId, value?.valueName]
      .some((part) => part?.toLocaleLowerCase().includes(needle))) return false;
    return true;
  }).sort((a, b) => b.createdTs.localeCompare(a.createdTs));
  const page = filtered.slice(offset, offset + limit).map((record) => ({
    ...record,
    stale: record.state !== "current" || record.status === "stale" || (!!snapshotId && record.snapshotId !== snapshotId),
  }));
  return ok({
    current: page.filter((record) => !record.stale),
    historical: page.filter((record) => record.stale),
    total: filtered.length,
    textBackend: "bounded-substring",
  });
}

async function reviewChains(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  if (data.goal !== undefined && !bounded(data.goal)) return fail("RESOURCE_LIMIT", "goal is too large");
  const values = (await kv.list<ValueIdentity>(KV.evidenceValues)).filter((value) => value.snapshotId === snapshot.id && value.state === "current");
  const valueMap = new Map(values.map((value) => [value.id, value]));
  const edges = (await kv.list<FlowEdge>(KV.evidenceFlows)).filter((edge) => edge.snapshotId === snapshot.id && edge.state === "current" && edge.isLatest && !["rejected", "stale"].includes(edge.status));
  const guards = (await kv.list<Guard>(KV.evidenceGuards)).filter((guard) => guard.snapshotId === snapshot.id && guard.state === "current");
  const guardsByEdge = new Map<string, Guard[]>();
  for (const guard of guards) guardsByEdge.set(guard.flowEdgeId, [...(guardsByEdge.get(guard.flowEdgeId) ?? []), guard]);
  const outgoing = new Map<string, FlowEdge[]>();
  for (const edge of edges) outgoing.set(edge.srcVid, [...(outgoing.get(edge.srcVid) ?? []), edge]);
  const goal = typeof data.goal === "string" ? data.goal.toLocaleLowerCase() : "";
  const sources = values.filter((value) => value.role === "source");
  const chains: Array<Record<string, unknown>> = [];
  const walk = (current: string, path: FlowEdge[], visited: Set<string>) => {
    if (chains.length >= MAX_CHAINS || path.length >= MAX_CHAIN_DEPTH) return;
    const value = valueMap.get(current);
    if (value?.role === "sink" && path.length > 0 && (!goal || [value.sinkType, value.valueName, value.symbolId].some((part) => part?.toLocaleLowerCase().includes(goal)))) {
      const steps = path.map((edge) => {
        const edgeGuards = guardsByEdge.get(edge.id) ?? [];
        const guardBlocked = edgeGuards.some((guard) => guard.status === "active");
        return { flowEdgeId: edge.id, srcVid: edge.srcVid, dstVid: edge.dstVid, status: edge.status, trust: edge.trust, guardBlocked };
      });
      const missingTransitions = steps.filter((step) => step.status !== "demonstrated" || step.guardBlocked);
      const contradicted = steps.some((step) => step.status === "blocked" || step.guardBlocked);
      const demonstrated = steps.every((step) => step.status === "demonstrated" && !step.guardBlocked);
      const supported = !contradicted && steps.every((step) => ["supported", "demonstrated"].includes(step.status));
      chains.push({
        sourceValueId: path[0]!.srcVid, sinkValueId: current, goal: value.sinkType ?? value.valueName,
        status: demonstrated ? "demonstrated" : contradicted ? "contradicted" : supported ? "supported" : "unresolved",
        impactState: demonstrated ? "demonstrated" : supported ? "suspected" : "unproven",
        demonstrated, steps, missingTransitions,
      });
    }
    for (const edge of outgoing.get(current) ?? []) {
      if (visited.has(edge.dstVid)) continue;
      walk(edge.dstVid, [...path, edge], new Set([...visited, edge.dstVid]));
    }
  };
  for (const source of sources) walk(source.id, [], new Set([source.id]));
  return ok({
    chains,
    established: chains.filter((chain) => chain.status === "demonstrated"),
    unresolved: chains.filter((chain) => !["demonstrated", "contradicted"].includes(String(chain.status))),
    contradicted: chains.filter((chain) => chain.status === "contradicted"),
    limitations: chains.some((chain) => chain.status !== "demonstrated") ? ["one or more explicit transitions or guard states remain unproven"] : [],
  });
}

async function claimCoverage(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const hypothesis = await kv.get<Hypothesis>(KV.evidenceHypotheses, String(data.hypothesisId ?? ""));
  if (!hypothesis) return fail("NOT_FOUND", `unknown hypothesis ${String(data.hypothesisId ?? "")}`);
  const links = (await kv.list<EvidenceLink>(KV.evidenceLinks)).filter((link) => link.hypothesisId === hypothesis.id);
  const evidence = await Promise.all(links.filter((link) => link.evidenceId).map((link) => kv.get<EvidenceRecord>(KV.evidenceRecords, link.evidenceId!)));
  const flows = await Promise.all(links.filter((link) => link.flowEdgeId).map((link) => kv.get<FlowEdge>(KV.evidenceFlows, link.flowEdgeId!)));
  const supporting = links.filter((link) => link.relation === "supports");
  const contradicting = links.filter((link) => link.relation === "contradicts");
  return ok({
    hypothesis,
    supporting,
    contradicting,
    direct: evidence.filter((item) => item && ["source_excerpt", "static_analysis", "dataflow"].includes(item.kind)),
    dynamic: evidence.filter((item) => item && ["crash", "test", "fuzz"].includes(item.kind)),
    modeled: flows.filter(Boolean),
    uncovered: supporting.length === 0,
    hasCounterEvidence: contradicting.length > 0,
  });
}

async function reclassifySink(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const old = await kv.get<ValueIdentity>(KV.evidenceValues, String(data.valueIdentityId ?? ""));
  if (!old) return fail("NOT_FOUND", `unknown value identity ${String(data.valueIdentityId ?? "")}`);
  if (old.role !== "sink" || old.state !== "current") return fail("CONFLICT", "only a current sink identity can be reclassified");
  if (!bounded(data.newSinkType) || !data.newSinkType.trim()) return fail("INVALID_ARGUMENT", "newSinkType is required");
  const payload = { ...data, idempotencyKey: undefined };
  return mutation(kv, "reclassify_sink", payload, data.idempotencyKey, async (idFor) => {
    const now = new Date().toISOString();
    const successor: ValueIdentity = {
      ...old, id: idFor("evval", "successor"), sinkType: data.newSinkType as string,
      state: "current", version: old.version + 1, createdTs: now,
    };
    delete successor.supersededBy;
    delete successor.staleReason;
    await kv.set(KV.evidenceValues, old.id, { ...old, state: "superseded", supersededBy: successor.id, staleReason: String(data.reason ?? "sink reclassified") });
    await kv.set(KV.evidenceValues, successor.id, successor);
    await addDependency(kv, old.snapshotId, "path", old.path, "value", successor.id);
    const affectedEdges: string[] = [];
    const successorEdges: string[] = [];
    for (const edge of await kv.list<FlowEdge>(KV.evidenceFlows)) {
      if (edge.state !== "current" || !edge.isLatest || (edge.srcVid !== old.id && edge.dstVid !== old.id)) continue;
      const next: FlowEdge = {
        ...edge, id: idFor("evflow", edge.id),
        srcVid: edge.srcVid === old.id ? successor.id : edge.srcVid,
        dstVid: edge.dstVid === old.id ? successor.id : edge.dstVid,
        status: "hypothesis", trust: "agent_asserted", provenance: agentOrigin("sink-reclassification"),
        state: "current", version: edge.version + 1, isLatest: true, createdTs: now,
      };
      delete next.evidenceId;
      delete next.supersededBy;
      delete next.staleReason;
      await kv.set(KV.evidenceFlows, edge.id, { ...edge, state: "superseded", status: "stale", isLatest: false, supersededBy: next.id, validToCommit: edge.validFromCommit, staleReason: String(data.reason ?? "sink reclassified") });
      await kv.set(KV.evidenceFlows, next.id, next);
      affectedEdges.push(edge.id);
      successorEdges.push(next.id);
      await lifecycle(kv, "flow", edge.id, "superseded", edge.snapshotId, String(data.reason ?? "sink reclassified"), next.id);
    }
    for (const hypothesis of await kv.list<Hypothesis>(KV.evidenceHypotheses)) {
      if (!hypothesis.supportingFlowEdgeIds.some((id) => affectedEdges.includes(id))) continue;
      await kv.set(KV.evidenceHypotheses, hypothesis.id, { ...hypothesis, status: "stale", state: "stale", staleReason: String(data.reason ?? "sink reclassified"), updatedTs: now });
      await lifecycle(kv, "hypothesis", hypothesis.id, "staled", hypothesis.snapshotId, String(data.reason ?? "sink reclassified"));
    }
    await lifecycle(kv, "value", old.id, "superseded", old.snapshotId, String(data.reason ?? "sink reclassified"), successor.id);
    await recordAudit(kv, "evidence_reclassify", "ev::reclassify-sink", [old.id, successor.id, ...affectedEdges, ...successorEdges], { reason: data.reason ?? "" });
    return ok({ newValueIdentityId: successor.id, supersededValueIdentityId: old.id, affectedEdges, successorEdges });
  });
}

async function staleRecord(kv: StateKV, targetKind: DependencyTargetKind, targetId: string, reason: string): Promise<boolean> {
  const now = new Date().toISOString();
  if (targetKind === "source_ref") {
    const item = await kv.get<SourceReference>(KV.evidenceSourceRefs, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceSourceRefs, targetId, { ...item, state: "stale", staleReason: reason });
  } else if (targetKind === "value") {
    const item = await kv.get<ValueIdentity>(KV.evidenceValues, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceValues, targetId, { ...item, state: "stale", staleReason: reason });
  } else if (targetKind === "flow") {
    const item = await kv.get<FlowEdge>(KV.evidenceFlows, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceFlows, targetId, { ...item, state: "stale", status: "stale", isLatest: false, staleReason: reason });
  } else if (targetKind === "evidence") {
    const item = await kv.get<EvidenceRecord>(KV.evidenceRecords, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceRecords, targetId, { ...item, state: "stale", status: "stale", staleReason: reason });
  } else if (targetKind === "hypothesis") {
    const item = await kv.get<Hypothesis>(KV.evidenceHypotheses, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceHypotheses, targetId, { ...item, state: "stale", status: "stale", staleReason: reason, updatedTs: now });
  } else if (targetKind === "validation") {
    const item = await kv.get<ValidationRun>(KV.evidenceValidationRuns, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceValidationRuns, targetId, { ...item, state: "stale", status: "inconclusive", staleReason: reason });
  } else {
    const item = await kv.get<Finding>(KV.evidenceFindings, targetId); if (!item || item.state !== "current") return false;
    await kv.set(KV.evidenceFindings, targetId, { ...item, state: "stale", status: "stale", impactState: "unproven", staleReason: reason });
  }
  await lifecycle(kv, targetKind, targetId, "staled", undefined, reason);
  return true;
}

async function invalidateDependencies(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  const changes = parseDependencies(data.changes);
  if (!Array.isArray(changes) || changes.length === 0) return Array.isArray(changes) ? fail("INVALID_ARGUMENT", "changes is required") : changes;
  const reason = typeof data.reason === "string" && data.reason ? data.reason.slice(0, MAX_FIELD) : "research input changed";
  if (data.newSnapshotId) {
    const next = await snapshotOrError(kv, data.newSnapshotId);
    if (isFailure(next)) return next;
    if (next.repoId !== snapshot.repoId) return fail("REVISION_MISMATCH", "replacement snapshot belongs to a different repository");
  }
  const payload = { snapshotId: snapshot.id, changes, reason, newSnapshotId: data.newSnapshotId };
  return mutation(kv, "invalidate_dependency_inputs", payload, data.idempotencyKey, async () => {
    const dependencies = (await kv.list<EvidenceDependency>(KV.evidenceDependencies)).filter((dependency) => dependency.snapshotId === snapshot.id);
    const affected = new Map<DependencyTargetKind, Set<string>>();
    const add = (kind: DependencyTargetKind, id: string) => {
      if (!affected.has(kind)) affected.set(kind, new Set());
      affected.get(kind)!.add(id);
    };
    for (const change of changes) for (const dependency of dependencies) {
      if (dependency.inputKind === change.kind && dependency.inputKey === change.key) add(dependency.targetKind, dependency.targetId);
    }
    const changedValueIds = affected.get("value") ?? new Set<string>();
    for (const edge of await kv.list<FlowEdge>(KV.evidenceFlows)) {
      if (edge.snapshotId === snapshot.id && (changedValueIds.has(edge.srcVid) || changedValueIds.has(edge.dstVid))) add("flow", edge.id);
    }
    const changedFlowIds = affected.get("flow") ?? new Set<string>();
    const changedEvidenceIds = affected.get("evidence") ?? new Set<string>();
    for (const hypothesis of await kv.list<Hypothesis>(KV.evidenceHypotheses)) {
      if (hypothesis.snapshotId === snapshot.id && (hypothesis.supportingFlowEdgeIds.some((id) => changedFlowIds.has(id)) || hypothesis.supportingEvidenceIds.some((id) => changedEvidenceIds.has(id)))) add("hypothesis", hypothesis.id);
    }
    const changedHypothesisIds = affected.get("hypothesis") ?? new Set<string>();
    for (const run of await kv.list<ValidationRun>(KV.evidenceValidationRuns)) if (run.hypothesisId && changedHypothesisIds.has(run.hypothesisId)) add("validation", run.id);
    for (const finding of await kv.list<Finding>(KV.evidenceFindings)) if (finding.hypothesisId && changedHypothesisIds.has(finding.hypothesisId)) add("finding", finding.id);
    const counts: Record<string, number> = {};
    for (const [kind, ids] of affected) for (const id of ids) if (await staleRecord(kv, kind, id, reason)) counts[kind] = (counts[kind] ?? 0) + 1;
    await recordAudit(kv, "evidence_invalidate", "ev::invalidate-dependencies", [...affected.values()].flatMap((ids) => [...ids]), { snapshotId: snapshot.id, changes, reason, counts });
    return ok({ snapshotId: snapshot.id, newSnapshotId: data.newSnapshotId ?? null, counts });
  });
}

async function invalidatePaths(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const paths = Array.isArray(data.changedPaths) ? data.changedPaths : typeof data.changedPaths === "string" ? data.changedPaths.split(",").map((path) => path.trim()).filter(Boolean) : [];
  if (!paths.length) return fail("INVALID_ARGUMENT", "changedPaths is required");
  if (paths.length > MAX_CHANGES || paths.some((path) => !validPath(path))) return fail("RESOURCE_LIMIT", "changedPaths contains too many or invalid paths");
  return invalidateDependencies(kv, {
    snapshotId: data.snapshotId,
    changes: paths.map((path) => ({ kind: "path", key: path })),
    reason: data.reason ?? "source changed",
    newSnapshotId: data.newSnapshotId,
    idempotencyKey: data.idempotencyKey,
  });
}

async function exportBundle(kv: StateKV, data: Record<string, unknown>): Promise<EvidenceResult> {
  const snapshot = await snapshotOrError(kv, data.snapshotId);
  if (isFailure(snapshot)) return snapshot;
  const limit = Number(data.limit ?? 100);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) return fail("RESOURCE_LIMIT", `limit must be 1-${MAX_LIMIT}`);
  const refs = (await kv.list<SourceReference>(KV.evidenceSourceRefs)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const values = (await kv.list<ValueIdentity>(KV.evidenceValues)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const flows = (await kv.list<FlowEdge>(KV.evidenceFlows)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const guards = (await kv.list<Guard>(KV.evidenceGuards)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const evidence = (await kv.list<EvidenceRecord>(KV.evidenceRecords)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const hypotheses = (await kv.list<Hypothesis>(KV.evidenceHypotheses)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const hypothesisIds = new Set(hypotheses.map((item) => item.id));
  const links = (await kv.list<EvidenceLink>(KV.evidenceLinks)).filter((item) => hypothesisIds.has(item.hypothesisId)).slice(0, limit);
  const validationRuns = (await kv.list<ValidationRun>(KV.evidenceValidationRuns)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const findings = (await kv.list<Finding>(KV.evidenceFindings)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const dependencies = (await kv.list<EvidenceDependency>(KV.evidenceDependencies)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const lifecycleEvents = (await kv.list<EvidenceLifecycleEvent>(KV.evidenceLifecycle)).filter((item) => item.snapshotId === snapshot.id).slice(0, limit);
  const artifacts: Array<Omit<EvidenceArtifact, "content">> = [];
  const artifactDigests = new Set([
    ...evidence.map((item) => item.rawArtifactSha256).filter(Boolean),
    ...validationRuns.map((item) => item.logArtifactSha256).filter(Boolean),
  ] as string[]);
  for (const digest of artifactDigests) {
    const artifact = await kv.get<EvidenceArtifact>(KV.evidenceArtifacts, digest);
    if (!artifact) return fail("NOT_FOUND", `bundle is incomplete: missing artifact ${digest}`);
    if (sha256(artifact.content) !== digest || Buffer.byteLength(artifact.content, "utf8") !== artifact.sizeBytes) return fail("CONFLICT", `bundle artifact ${digest} is corrupt`);
    const { content: _content, ...metadata } = artifact;
    artifacts.push(metadata);
  }
  await lifecycle(kv, "snapshot", snapshot.id, "exported", snapshot.id);
  await recordAudit(kv, "evidence_export", "ev::export-bundle", [snapshot.id], { limit, artifactCount: artifacts.length });
  return ok({
    bundleVersion: 1,
    snapshot,
    sourceReferences: refs,
    valueIdentities: values,
    flowEdges: flows,
    guards,
    evidence,
    hypotheses,
    links,
    validationRuns,
    findings,
    dependencies,
    lifecycleEvents,
    artifacts,
    disclosurePolicy: { internalSeverityOmitted: true, artifactContentsOmittedFromMcp: true },
  });
}

export function registerEvidenceFunctions(sdk: IIIClient, kv: StateKV): void {
  sdk.registerFunction("ev::register-snapshot", (data: Record<string, unknown>) => registerSnapshot(kv, data ?? {}));
  sdk.registerFunction("ev::record-source", (data: Record<string, unknown>) => recordSourceReference(kv, data ?? {}));
  sdk.registerFunction("ev::record-value", (data: Record<string, unknown>) => recordValueIdentity(kv, data ?? {}));
  sdk.registerFunction("ev::record-evidence", (data: Record<string, unknown>) => recordEvidence(kv, data ?? {}));
  sdk.registerFunction("ev::link-flow", (data: Record<string, unknown>) => linkFlow(kv, data ?? {}));
  sdk.registerFunction("ev::record-hypothesis", (data: Record<string, unknown>) => recordHypothesis(kv, data ?? {}));
  sdk.registerFunction("ev::record-counter", (data: Record<string, unknown>) => recordCounterEvidence(kv, data ?? {}));
  sdk.registerFunction("ev::record-validation", (data: Record<string, unknown>) => recordValidation(kv, data ?? {}));
  sdk.registerFunction("ev::query", (data: Record<string, unknown>) => queryEvidence(kv, data ?? {}));
  sdk.registerFunction("ev::review-chain", (data: Record<string, unknown>) => reviewChains(kv, data ?? {}));
  sdk.registerFunction("ev::claim-coverage", (data: Record<string, unknown>) => claimCoverage(kv, data ?? {}));
  sdk.registerFunction("ev::reclassify-sink", (data: Record<string, unknown>) => reclassifySink(kv, data ?? {}));
  sdk.registerFunction("ev::invalidate-paths", (data: Record<string, unknown>) => invalidatePaths(kv, data ?? {}));
  sdk.registerFunction("ev::invalidate-dependencies", (data: Record<string, unknown>) => invalidateDependencies(kv, data ?? {}));
  sdk.registerFunction("ev::export-bundle", (data: Record<string, unknown>) => exportBundle(kv, data ?? {}));
}
