import type { IIIClient } from "iii-sdk";

const TOOL_TO_FUNCTION = {
  evidence_register_snapshot: "ev::register-snapshot",
  evidence_record_source: "ev::record-source",
  evidence_record_value: "ev::record-value",
  evidence_record: "ev::record-evidence",
  evidence_link_flow: "ev::link-flow",
  evidence_record_hypothesis: "ev::record-hypothesis",
  evidence_record_counter: "ev::record-counter",
  evidence_record_validation: "ev::record-validation",
  evidence_query: "ev::query",
  evidence_review_chain: "ev::review-chain",
  evidence_claim_coverage: "ev::claim-coverage",
  evidence_reclassify_sink: "ev::reclassify-sink",
  evidence_invalidate_paths: "ev::invalidate-paths",
  evidence_invalidate_dependencies: "ev::invalidate-dependencies",
  evidence_export_bundle: "ev::export-bundle",
} as const;

export type EvidenceToolName = keyof typeof TOOL_TO_FUNCTION;

export function isEvidenceToolName(name: string): name is EvidenceToolName {
  return Object.hasOwn(TOOL_TO_FUNCTION, name);
}

function csv(value: unknown): string[] {
  if (Array.isArray(value)) return value.filter((item): item is string => typeof item === "string" && !!item.trim()).map((item) => item.trim());
  return typeof value === "string" ? value.split(",").map((item) => item.trim()).filter(Boolean) : [];
}

function jsonArray(value: unknown, field: string): unknown[] {
  if (Array.isArray(value)) return value;
  if (typeof value !== "string" || !value.trim()) return [];
  const parsed = JSON.parse(value);
  if (!Array.isArray(parsed)) throw new Error(`${field} must be a JSON array`);
  return parsed;
}

export function evidenceFunctionId(name: EvidenceToolName): string {
  return TOOL_TO_FUNCTION[name];
}

export function buildEvidencePublicPayload(name: EvidenceToolName, args: Record<string, unknown>): Record<string, unknown> {
  const common = typeof args.idempotencyKey === "string" ? { idempotencyKey: args.idempotencyKey } : {};
  switch (name) {
    case "evidence_register_snapshot":
      return { repoId: args.repoId, commitId: args.commitId, dirty: args.dirty, patchDigest: args.patchDigest, treeDigest: args.treeDigest, scope: args.scope, platform: args.platform, indexId: args.indexId, ...common };
    case "evidence_record_source":
      return { snapshotId: args.snapshotId, path: args.path, startLine: args.startLine, endLine: args.endLine, symbolId: args.symbolId, language: args.language, excerpt: args.excerpt, ...common };
    case "evidence_record_value":
      return { snapshotId: args.snapshotId, path: args.path, valueName: args.valueName, role: args.role, symbolId: args.symbolId, startLine: args.startLine, endLine: args.endLine, sinkType: args.sinkType, language: args.language, ...common };
    case "evidence_record":
      return { snapshotId: args.snapshotId, kind: args.kind, raw: args.raw, projection: args.projection, status: args.status, tool: args.tool, toolVersion: args.toolVersion, queryId: args.queryId, valueIdentityId: args.valueIdentityId, dependencies: jsonArray(args.dependenciesJson, "dependenciesJson"), ...common };
    case "evidence_link_flow":
      return { snapshotId: args.snapshotId, srcVid: args.srcVid, dstVid: args.dstVid, kind: args.kind, status: args.status, evidenceId: args.evidenceId, callerSymbol: args.callerSymbol, calleeSymbol: args.calleeSymbol, argIndex: args.argIndex, paramName: args.paramName, ...common };
    case "evidence_record_hypothesis":
      return { snapshotId: args.snapshotId, statement: args.statement, invariant: args.invariant, scope: args.scope, nextAction: args.nextAction, supportingEvidenceIds: csv(args.supportingEvidenceIds), supportingFlowEdgeIds: csv(args.supportingFlowEdgeIds), ...common };
    case "evidence_record_counter":
      return { hypothesisId: args.hypothesisId, evidenceId: args.evidenceId, flowEdgeId: args.flowEdgeId, rationale: args.rationale, ...common };
    case "evidence_record_validation":
      return { snapshotId: args.snapshotId, hypothesisId: args.hypothesisId, kind: args.kind, status: args.status, logs: args.logs, repeatSummary: args.repeatSummary, buildDigest: args.buildDigest, configDigest: args.configDigest, dependencies: jsonArray(args.dependenciesJson, "dependenciesJson"), ...common };
    case "evidence_query":
      return { snapshotId: args.snapshotId, text: args.text, kind: args.kind, status: args.status, path: args.path, symbolId: args.symbolId, limit: args.limit, offset: args.offset };
    case "evidence_review_chain":
      return { snapshotId: args.snapshotId, goal: args.goal };
    case "evidence_claim_coverage":
      return { hypothesisId: args.hypothesisId };
    case "evidence_reclassify_sink":
      return { valueIdentityId: args.valueIdentityId, newSinkType: args.newSinkType, reason: args.reason, ...common };
    case "evidence_invalidate_paths":
      return { snapshotId: args.snapshotId, changedPaths: csv(args.changedPaths), reason: args.reason, newSnapshotId: args.newSnapshotId, ...common };
    case "evidence_invalidate_dependencies":
      return { snapshotId: args.snapshotId, changes: jsonArray(args.changesJson, "changesJson"), reason: args.reason, newSnapshotId: args.newSnapshotId, ...common };
    case "evidence_export_bundle":
      return { snapshotId: args.snapshotId, limit: args.limit };
  }
}

export async function callEvidenceMcpTool(
  sdk: IIIClient,
  name: EvidenceToolName,
  args: Record<string, unknown>,
): Promise<{ status_code: number; body: unknown }> {
  let payload: Record<string, unknown>;
  try {
    payload = buildEvidencePublicPayload(name, args);
  } catch (error) {
    return { status_code: 400, body: { error: (error as Error).message } };
  }
  const result = await sdk.trigger({ function_id: evidenceFunctionId(name), payload });
  return {
    status_code: 200,
    body: { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] },
  };
}
