import type { Origin } from "../types.js";

export type TrustLevel = "agent_asserted" | "tool_verified" | "human_verified";
export type EvidenceStatus = "observed" | "supported" | "reproduced" | "rejected" | "stale";
export type FlowStatus = "hypothesis" | "supported" | "demonstrated" | "rejected" | "blocked" | "stale";
export type ImpactState = "unproven" | "suspected" | "demonstrated";
export type ValueRole = "source" | "sink" | "transform" | "param" | "return" | "field" | "value";
export type RecordState = "current" | "stale" | "superseded";
export type DependencyInputKind =
  | "path"
  | "header"
  | "generated_input"
  | "build_flag"
  | "analysis_model"
  | "boundary_model"
  | "config";
export type DependencyTargetKind =
  | "source_ref"
  | "value"
  | "flow"
  | "evidence"
  | "hypothesis"
  | "validation"
  | "finding";

export const STRONG_TRUST: ReadonlySet<TrustLevel> = new Set([
  "tool_verified",
  "human_verified",
]);

export interface EvidenceSnapshot {
  id: string;
  repoId: string;
  commitId: string;
  dirty: boolean;
  patchDigest?: string;
  treeDigest?: string;
  scope?: string;
  platform?: string;
  indexId?: string;
  createdTs: string;
}

export interface SourceReference {
  id: string;
  snapshotId: string;
  path: string;
  startLine: number;
  endLine: number;
  symbolId?: string;
  language?: string;
  excerpt?: string;
  fileDigest?: string;
  state: RecordState;
  staleReason?: string;
  createdTs: string;
}

export interface ValueIdentity {
  id: string;
  snapshotId: string;
  path: string;
  symbolId?: string;
  valueName: string;
  startLine: number;
  endLine: number;
  role: ValueRole;
  sinkType?: string;
  language?: string;
  origin: Origin;
  state: RecordState;
  version: number;
  supersededBy?: string;
  staleReason?: string;
  createdTs: string;
}

export interface EvidenceArtifact {
  sha256: string;
  sizeBytes: number;
  content: string;
  encoding: "utf8";
  createdTs: string;
}

export interface EvidenceRecord {
  id: string;
  snapshotId: string;
  kind: "static_analysis" | "dataflow" | "crash" | "test" | "source_excerpt" | "build" | "fuzz";
  status: EvidenceStatus;
  trust: TrustLevel;
  rawArtifactSha256?: string;
  projection?: string;
  valueIdentityId?: string;
  tool?: string;
  toolVersion?: string;
  queryId?: string;
  origin: Origin;
  state: RecordState;
  version: number;
  supersededBy?: string;
  staleReason?: string;
  createdTs: string;
}

export interface FlowEdge {
  id: string;
  snapshotId: string;
  srcVid: string;
  dstVid: string;
  kind: "intraprocedural" | "interprocedural" | "field" | "return" | "alias";
  status: FlowStatus;
  trust: TrustLevel;
  evidenceId?: string;
  callerSymbol?: string;
  calleeSymbol?: string;
  argIndex?: number;
  paramName?: string;
  provenance: Origin;
  validFromCommit: string;
  validToCommit?: string;
  state: RecordState;
  version: number;
  supersededBy?: string;
  staleReason?: string;
  isLatest: boolean;
  createdTs: string;
}

export interface Guard {
  id: string;
  snapshotId: string;
  flowEdgeId: string;
  guardSymbol?: string;
  kind: "sanitizer" | "validator" | "bounds" | "type-check";
  status: "active" | "bypassed" | "incomplete" | "rejected" | "stale";
  evidenceId?: string;
  trust: TrustLevel;
  origin: Origin;
  state: RecordState;
  staleReason?: string;
  createdTs: string;
}

export interface Hypothesis {
  id: string;
  snapshotId?: string;
  statement: string;
  invariant?: string;
  scope?: string;
  nextAction?: string;
  status: "open" | "supported" | "challenged" | "refuted" | "stale";
  supportingEvidenceIds: string[];
  supportingFlowEdgeIds: string[];
  state: RecordState;
  staleReason?: string;
  createdTs: string;
  updatedTs: string;
}

export interface EvidenceLink {
  id: string;
  hypothesisId: string;
  relation: "supports" | "contradicts";
  evidenceId?: string;
  flowEdgeId?: string;
  rationale?: string;
  createdTs: string;
}

export interface ValidationRun {
  id: string;
  snapshotId?: string;
  hypothesisId?: string;
  kind: "test" | "build" | "repro" | "fuzz";
  status: "not_run" | "running" | "passed" | "failed" | "inconclusive";
  trust: TrustLevel;
  logArtifactSha256?: string;
  repeatSummary?: string;
  buildDigest?: string;
  configDigest?: string;
  origin: Origin;
  state: RecordState;
  staleReason?: string;
  createdTs: string;
}

export interface Finding {
  id: string;
  snapshotId: string;
  hypothesisId?: string;
  title: string;
  rootCause?: string;
  impactState: ImpactState;
  fingerprint: string;
  status: "draft" | "in_review" | "accepted" | "rejected" | "duplicate" | "closed" | "stale";
  state: RecordState;
  version: number;
  staleReason?: string;
  createdTs: string;
}

export interface EvidenceDependency {
  id: string;
  snapshotId: string;
  inputKind: DependencyInputKind;
  inputKey: string;
  targetKind: DependencyTargetKind;
  targetId: string;
  createdTs: string;
}

export interface EvidenceLifecycleEvent {
  id: string;
  snapshotId?: string;
  recordKind: DependencyTargetKind | "snapshot" | "guard";
  recordId: string;
  event: "created" | "staled" | "superseded" | "rejected" | "exported";
  reason?: string;
  replacementId?: string;
  createdTs: string;
}

export interface EvidenceIdempotencyRecord {
  key: string;
  operation: string;
  payloadHash: string;
  result: unknown;
  createdTs: string;
}

export interface AttestedOrigin extends Origin {
  channel: "tool" | "import" | "user";
}

/** Only trusted in-process importers/reviewers may call this helper. */
export function trustFromAttestedOrigin(origin: AttestedOrigin): TrustLevel {
  return origin.channel === "user" ? "human_verified" : "tool_verified";
}
